def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays2 = set()
    rays_vertical = set()
    crosses = []

    def put(r, c, color):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = color

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                put(r, c + 1, 5)
                put(r, c + 2, 5)
                put(r - 1, c + 2, 1)
            elif color == 2:
                for d in range(1, 5):
                    if 0 <= c - d < w:
                        put(r, c - d, 2 if d == 4 else 5)
                        rays2.add((r, c - d))
                rays2.add((r, c))
            elif color == 3:
                for d in range(1, 4):
                    if r + d < h:
                        put(r + d, c, 3 if d == 3 else 5)
                        rays_vertical.add((r + d, c))
                rays_vertical.add((r, c))
            elif color == 6:
                length = min(6, r)
                for d in range(1, length + 1):
                    put(r - d, c, 6 if d == length else 5)
                    rays_vertical.add((r - d, c))
                rays_vertical.add((r, c))

    for r, c in rays2:
        if (r, c) in rays_vertical:
            crosses.append((r, c))

    for r, c in crosses:
        put(r, c, 4)
        d = 1
        while r + d < h and c - d >= 0:
            put(r + d, c - d, 4)
            d += 1

    return out
